"คริติคอล · โชค":"Critical · Luck",
"ลานครูแห่งอโยธยา":"Masters' Court of Ayothaya",
"ขุนอินทรเดช":"Khun Inthradet",
"ครูดาบ":"Sword Kru",
"ดาบที่มั่นคงเริ่มจากใจที่ไม่หวั่นไหว จงออกปกป้องชาวบ้าน แล้วกลับมารับคำสอนจากข้า":"A steady blade begins with an unshaken heart. Go protect the villagers, then return to learn from me.",
"ครูหญิงพิกุล":"Kru Ying Phikun",
"ครูทวน":"Spear Kru",
"ปลายทวนมีไว้รักษาระยะและคุ้มครองสหาย เจ้าพร้อมเรียนรู้จังหวะของมันหรือยัง":"The spear tip keeps distance and protects comrades. Are you ready to learn its rhythm?",
"พรานแม่แก้ว":"Hunter Mae Kaeo",
"ครูพราน":"Hunter Kru",
"ป่ามีภาษาของมัน ก่อนปล่อยศร เจ้าต้องมองเส้นทางกลับบ้านของทุกคนให้เห็น":"The forest has its own language. Before loosing an arrow, you must see everyone's path home.",
"ครูคง":"Kru Khong",
"ยืนให้มั่น หายใจให้เป็น แล้วค่อยออกหมัด ฝีมือของเจ้ามีไว้ปกป้องผู้อ่อนแอ":"Stand firm, breathe well, then throw your fist. Your skill is for protecting the weak.",
"แม่เงาจันทร์":"Mae Ngao Chan",
"ครูมีดคู่":"Twin Dagger Kru",
"ความไวเพียงอย่างเดียวไม่พอ เจ้าต้องรู้ว่าเมื่อใดควรเข้าหา และเมื่อใดควรถอย":"Speed alone is not enough. You must know when to close in and when to retreat.",
"ปู่คำสิงห์":"Grandpa Kham Singh",
"ครูอาคม":"Sorcery Kru",
"ทุกดวงวิญญาณเคยมีชื่อ จงใช้วิชาเพื่อคลายทุกข์ มิใช่ผูกทุกสิ่งไว้กับตน":"Every spirit once had a name. Use your art to ease suffering, not to bind everything to yourself.",
"หลวงพ่อปัญญาธร":"Luang Pho Panyathon",
"ครูสายเมตตา":"Kru Sai Metta",
"กำลังใจอันสงบช่วยคุ้มครองผู้คนได้ จงไปบรรเทาภัยนอกกำแพง แล้วกลับมาเล่าให้อาตมาฟัง":"A calm spirit can protect people. Go ease the dangers outside the walls, then come tell me about it.",
"แม่ชีบุญเรือน":"Mae Chi Bunruean",
"เมตตาคือการลงมือช่วยผู้อื่น พระและแม่ชีเรียนบททดสอบเดียวกัน เลือกเส้นทางที่ใจเจ้าพร้อมเถิด":"Compassion is acting to help others. Monks and Nuns take the same trial. Choose the path your heart is ready for.",
"หุ่นฟางพันเชือก (โรงสีใต้เงาจันทร์)":"Rope-Wrapped Scarecrow (Moonshadow Mill)",
"พญาวานรบึง (บึงบัวต้องมนตร์)":"Marsh Ape King (Enchanted Lotus Marsh)",
"แม่ค้า":"Merchant Woman",
"ผักสดจากทุ่งมาถึงแล้วจ้ะ วันนี้ตลาดคึกคักดีนะ":"Fresh vegetables from the fields have arrived! The market is lively today.",
"คนหาบของ":"Porter",
"ขอทางหน่อยนะ กำลังขนของไปส่งตลาด เดี๋ยวก็ได้พักแล้ว":"Excuse me, I'm carrying goods to the market. I'll get to rest soon.",
"คนขายดอกไม้":"Flower Seller",
"ดอกไม้หอม ๆ สำหรับไหว้ครูจ้ะ ลานครูอยู่ย่านลานสำนักทางเหนือของตลาด":"Fragrant flowers for honoring your Kru! The Masters' Court is in the school quarter north of the market.",
"พ่อครัว":"Cook",
"เดินเหนื่อยก็พักก่อนนะ กลิ่นข้าวหอม ๆ ช่วยให้คิดถึงบ้านเสมอ":"Rest if you're tired from walking. The smell of fragrant rice always brings thoughts of home.",
"ชาวนา":"Farmer",
"นอกกำแพงมีหุ่นฟางเดินได้ ข้าฝากพวกนักเดินทางดูแลทุ่งด้วยนะ":"Walking scarecrows roam outside the walls. I count on travelers to look after the fields.",
"คนเรือ":"Boatman",
"คลองเชื่อมทุกย่านไว้ด้วยกัน จะข้ามฟากก็ใช้สะพานนะ":"The canals link every quarter. To cross over, use the bridge.",
"ผู้เฒ่า":"Elder",
"ครูทั้งหลายรวมตัวอยู่ที่ลานครู ฝึกจน Job ตันก่อน จึงรับบททดสอบอาชีพได้":"The Krus gather at the Masters' Court. Max out your Job first, then you can take the Class trial.",
"ช่างสาน":"Weaver",
"ข้าจะเอาเสื่อไปส่งเรือนช่าง เจ้าชอบลายดอกพิกุลหรือลายขัดกันล่ะ":"I'm taking mats to the craftsmen's house. Do you prefer the bullet-wood flower pattern or the plain weave?",
"โหลดภาพชาวเมืองไม่ได้":"Could not load townsfolk image",
"เปลี่ยนอาชีพเมื่อ Job ตัน  ·  Job 10 → อาชีพ  ·  Job 40 → Master":"Change Class when Job is maxed  ·  Job 10 → Class  ·  Job 40 → Master",
"ทางเดินทาง":"Path",
"ตลาดกลาง":"Central Market",
