"ผจญภัยในอยุธยาแห่งความเชื่อ ตีบวกอาวุธ ล่าบอส ตั้งกิลด์ยึดป้อมโรงสี แล้วประลองชิงอันดับทุกสัปดาห์ — เปิดเบราว์เซอร์แล้วเล่นได้ทันที ทั้งคอมและมือถือ":"Adventure through the Ayutthaya of folk belief. Refine weapons, hunt bosses, form a Guild to seize the Mill Fortress, and duel for weekly rankings. Open your browser and play at once, on PC or mobile.",
"เล่นเลย":"Play Now",
"เข้าร่วม Discord":"Join Discord",
