"ทุกอย่างหาได้จากการเล่น ของดรอปจากมอนกลายเป็นยา อาหาร และหินตีบวก หมุนเวียนในตลาดของผู้เล่น":"Everything comes from play. Monster drops become potions, food and refine stones, circulating in the player market.",
"7 อาชีพ · สาย Master":"7 Classes · Master Path",
"เริ่มจากผู้ฝึกตน เลือกอาชีพที่ลานครู ผ่านบททดสอบ แล้วไต่สู่ Master":"Start as a Novice, pick a Class at the Masters' Court, pass the trials, and climb to Master.",
"ตีบวก +10":"Refine +10",
"+1 ถึง +4 ไม่มีวันแตก ตั้งแต่ +5 ลุ้นสุดตัว มีเหล็กไหลและยันต์กันแตกช่วย":"+1 to +4 never break. From +5 it's a gamble, helped by Lek Lai and Anti-Break Talismans.",
"การ์ดมอนสเตอร์":"Monster Cards",
"ทุกมอนมีการ์ดของตัวเอง ใส่ในอุปกรณ์เพิ่มพลังแบบถาวร":"Every monster has its own Card. Slot it into gear for permanent power.",
