"ล่อจับมอนตัวเล็ก ฟักไข่ เลี้ยงจนสนิทแล้วได้สเตตัสติดตัว":"Lure and tame small monsters, hatch eggs, and bond with them to gain stats.",
"กิลด์วอร์ยึดป้อม":"Guild War Fortress Siege",
