"เริ่มจากสกิลแถวบน · อัปให้ถึงขั้นที่กำหนดเพื่อปลดล็อกสกิลถัดไป (เรียนฟรี) · ขั้น 2–4 ใช้ 1 แต้ม · ขั้น 5 และ 10 ต้องผ่านเควสต์":"Start from the top-row Skills · Raise to the required rank to unlock the next Skill (free to learn) · Ranks 2–4 cost 1 point · Ranks 5 and 10 require a Quest",
