"ประทีปดวงสุดท้ายกลับมาแล้ว อยุธยาติดค้างบุญคุณเจ้าอีกครั้ง คนเก่งอย่างเจ้าควรมีพวกพ้องนะ":"The last lamp is back. Ayutthaya owes you again. A talent like you should have companions.",
