"เมืองหลวง · ท่าเรือ ตลาด และสวนประทีป":"Capital · Harbor, Market, and Lantern Garden",
"ยินดีต้อนรับสู่อยุธยา เมืองนี้ปลอดภัย เดินตามทางขึ้นไปจะถึงลานกลางเมืองกับตลาดแม่บัว คืนก่อนประทีปตามท่าน้ำดับลงพร้อมกัน… ข้าอยากรู้ว่าเกิดอะไรขึ้น":"Welcome to Ayutthaya. This town is safe. Follow the path up to reach the central square and Mae Bua Market. Last night, the lanterns along the piers all went out at once... I wonder what happened.",
"พักให้หายเหนื่อยก่อน ผู้ฝึกตน เมืองกำลังเตรียมงานประทีป หากเจ้าจะช่วย เริ่มจากทำความรู้จักผู้คนที่ท่าเรือและตลาดก่อน":"Rest first, Novice. The town is preparing for the Lantern Festival. If you wish to help, start by getting to know the folk at the harbor and market.",
"ตลาดยินดีต้อนรับจ้ะ ช่วงนี้เรือส่งของมาช้ากว่าปกติ แม่ได้ยินเสียงระฆังจากสวน ทั้งที่ไม่มีใครอยู่ที่ศาล":"Welcome to the market, dear. Supply boats have been later than usual. I heard a bell ringing from the garden, though no one is at the shrine.",
"ลานครูอยู่ข้างหน้านี้ ครูแต่ละสายรอรับผู้ฝึกตนระดับ 25 และศิษย์ระดับ 60 มาทำบททดสอบ":"The Masters' Court is just ahead. Each path's Kru awaits Novices at level 25 and disciples at level 60 for their trials.",
"เมื่อวานข้าเห็นแสงเล็ก ๆ ลอยอยู่ข้างศาลในสวน! ลองเดินชมดูสิ แต่ยังอย่าเพิ่งออกนอกเมืองนะ":"Yesterday I saw tiny lights floating beside the shrine in the garden! Go take a look, but don't leave town yet.",
"ประทีปมิได้ส่องเพียงทางเดิน แต่เตือนให้ผู้คนระลึกถึงกัน หากสายใยขวัญอ่อนลง เราต้องเริ่มดูแลจากบ้านของเราเอง":"Lanterns light more than the path; they remind people to remember one another. If the threads of spirit grow weak, we must begin by tending our own homes.",
"ท่าเรือเจ้าพระยา":"Chao Phraya Pier",
"ลานกลางเมือง":"Central Square",
"ย่านเรือนช่าง":"Artisans' Quarter",
"สวนประทีป":"Lantern Garden",
"วัดริมคลอง":"Canalside Temple",
