"ที่นี่คือทุ่งชุมพลของกิลด์เจ้า ยิ่งกิลด์บริจาคเข้าคลังมาก ก็ยิ่งปักธงทิว สร้างโรงศัสตรา และนำช้างม้าศึกมาประจำทุ่งได้ ทางใต้คือประตูกลับเมืองหลวง":"This is your guild's Mustering Field. The more the guild donates to its treasury, the more banners, armouries and war elephants it can bring here. The south gate leads back to the capital.",
