 "จุติให้ถึงขั้นสุดท้าย แข่งค่าพลัง หรือพิสูจน์ฝีมือในสังเวียน รางวัลหลักเป็นทองแท่ง ให้เลือกอัญเชิญกาชาเอง": "Reach the final rebirth, compete for power or prove yourself in the arena. Gold Bars are the main reward, so you can choose your own gacha summons.",
 "ดูรางวัลจุติ": "View Rebirth Rewards",
 "ดูรางวัลค่าพลัง": "View Power Rewards",
 "ดูรางวัลประลอง": "View Arena Rewards",
 "พรีวิวเท่านั้น · ยังไม่ล็อกรางวัล วันปิดรับ หรือวันส่งของทางจดหมาย ข้อมูลอันดับก่อนเริ่มกิจกรรมจะไม่ถูกนำมายืนยันรางวัลจากหน้านี้": "Preview only. Rewards, entry deadline and mail delivery date are not final. Rankings from before the event cannot establish reward eligibility here.",
 "ภาพกิจกรรม CBT: นักอาคมจุติกลางวงดอกบัว แชมป์บนแท่นรางวัล และผู้เล่นประลองดาบ": "CBT artwork: a spellcaster reborn in lotus light, champions on a podium and a sword duel",
 "ตราดอกบัวผู้บุกเบิก CBT": "CBT pioneers' lotus crest",
 "เป้าหมายส่วนบุคคล · ไม่จำกัดจำนวนผู้สำเร็จ": "Personal goal · No limit on qualifying players",
 "ก้าวข้ามวัฏสงสาร จุติครบขั้น 10": "Transcend the cycle: complete Rebirth 10",
 "ทุกคนที่ทำครบเงื่อนไขในช่วงกิจกรรมมีสิทธิ์รับรางวัล ไม่ได้จำกัดเฉพาะคนที่ถึงก่อน": "Everyone who completes the requirements during the event can qualify. Rewards are not limited to the first players to finish.",
 "จุติปัจจุบันของตัวละคร": "This character's current rebirth",
 "แสดงเพื่อทดลองหน้าจอเท่านั้น · แม้ครบแล้วก็ยังไม่บันทึกสิทธิ์ในพรีวิวนี้": "For preview only. Reaching the goal does not record eligibility yet.",
 "ต้องตรวจเวลาไปถึงจุติขั้น 10 จากการเล่นจริงก่อนสรุประยะเวลากิจกรรม เพื่อให้เป้าหมายทำถึงได้โดยไม่บังคับให้เล่นทั้งวัน": "Measure the actual time needed to reach Rebirth 10 before setting the event duration, so the goal is achievable without playing all day.",
 "จุติปัจจุบัน {3} จาก 10 ขั้น": "Current rebirth: {3} of 10",
 "อันดับค่าพลัง CBT": "CBT Power Rankings",
 "เก้าขุนพลแห่งอโยธยา": "Nine Champions of Ayothaya",
 "เสนอให้ใช้ค่าพลังจากเซิร์ฟเวอร์ ณ เวลาปิดกิจกรรม และเลือกตัวละครที่ดีที่สุดเพียง 1 ตัวต่อบัญชีในหมวดนี้ ไม่รวมบัญชีทีมงานหรือตัวละครทดสอบของทีม": "Proposal: use server-recorded power when the event closes, with only the best character per account in this category. Staff and team test characters are excluded.",
 "ยังไม่กำหนดเวลาปิดกิจกรรม จึงยังไม่มีการล็อกอันดับ CBT · ไม่ใช้ตัวเลขอันดับปัจจุบันเป็นผลตัดสิน": "The closing time is not set, so CBT rankings have not been locked. Current rankings are not final results.",
 "อันดับประลอง CBT · คิวจับคู่โดยเซิร์ฟเวอร์": "CBT Arena Rankings · Server Matchmaking",
 "ชนะด้วยฝีมือ ผ่านการค้นหาคู่": "Prove your skill through matchmaking",
 "ท้าดวลกันเอง = ไม่นับ CBT": "Manual challenges do not count toward CBT",
 "ระบบประลองเดิมยังแยกอยู่ต่างหาก หน้าพรีวิวนี้ไม่ดึงคะแนนท้าดวลเดิมมาเป็นคะแนนกิจกรรม": "The existing duel system remains separate. This preview does not use old challenge scores for the event.",
 "ค้นหาคู่ประลอง · รอเปิดระบบ CBT": "Find Arena Opponent · CBT System Not Open Yet",
 "กติกาป้องกันปั๊มคะแนนที่เสนอ": "Proposed Rules Against Score Farming",
 "คิวประลองและตัวนับคะแนน CBT ยังไม่เปิดใช้งาน กติกาข้างต้นเป็นข้อเสนอที่ต้องทำและตรวจฝั่งเซิร์ฟเวอร์ก่อนเริ่มแข่งขันจริง": "The CBT matchmaking queue and score tracking are not active yet. These proposed rules must be implemented and checked on the server before competition starts.",
 "ข้อเสนอเพิ่มเติม · ยังไม่ได้เปิดรับสิทธิ์": "Additional Proposals · Eligibility Not Active Yet",
 "คนไม่แข่งอันดับ ก็เป็นผู้บุกเบิกได้": "You can be a pioneer without competing for rank",
 "แนวทางรับรางวัล": "Proposed Reward Delivery",
 "เสนอให้เก็บสิทธิ์ตามบัญชีและส่งทางจดหมายตอนเปิดจริง ให้ผู้เล่นรับทองแท่งไปเลือกสุ่มกาชาเอง วันแจกและรายการรางวัลต้องยืนยันก่อนประกาศใช้": "Proposal: keep eligibility per account and deliver rewards by mail at launch. Players can use Gold Bars for their own gacha choices. Delivery dates and rewards must be confirmed before activation.",
