 "ให้ผู้เล่นทั่วไปมีเป้าหมาย โดยไม่ต้องแข่งกับคนเล่นทั้งวัน": "Give everyday players a goal without requiring them to compete with people who play all day",
 "นักสำรวจเรื่องราว": "Story Explorer",
 "ผ่านเนื้อเรื่องบทแรก": "Complete the first story chapter",
 "ชวนให้ลองเควส แผนที่ และระบบที่ต้องทดสอบจริง": "Encourage testing of the actual quests, maps and game systems",
 "ช่วยตรวจบั๊กที่ยืนยันแล้ว": "Help Confirm a Bug",
 "ส่งบั๊กพร้อมขั้นตอนทำซ้ำ และทีมงานตรวจยืนยัน": "Report a bug with steps to reproduce it and have the team verify it",
 "เสนอให้รับครั้งเดียวต่อบัญชี ไม่ใช่ให้ซ้ำทุกข้อความที่ส่ง": "Proposed limit: once per account, rather than once for every report submitted",
 "นับเฉพาะแมตช์ที่เซิร์ฟเวอร์จับคู่ผ่านปุ่มค้นหาคู่ประลอง": "Only server-made matches started through Find Opponent count",
