 "บัญชีเดียวกันเล่นเจอกันไม่รับคะแนน แม้เป็นคนละตัวละคร": "Characters on the same account cannot earn points against each other",
 "เสนอให้คู่เดิมนับคะแนนได้ 1 ครั้งต่อวัน และนับไม่เกิน 10 แมตช์ต่อวัน": "Proposal: count the same opponent once per day, with at most 10 scored matches per day",
